SELECT (CASE WHEN p.gender = 'F' AND EXTRACT(YEAR FROM AGE(p.anchor_year)) BETWEEN 47 AND 57 THEN COUNT(DISTINCT a.subject_id) END) AS patient_count, (CASE WHEN p.gender = 'F' AND EXTRACT(YEAR FROM AGE(p.anchor_year)) BETWEEN 47 AND 57 THEN AVG(CASE WHEN a.los BETWEEN 1 AND 4 THEN 1 ELSE 0 END) END) AS avg_procedures_los_1_4_days, (CASE WHEN p.gender = 'F' AND EXTRACT(YEAR FROM AGE(p.anchor_year)) BETWEEN 47 AND 57 THEN AVG(CASE WHEN a.los BETWEEN 5 AND 8 THEN 1 ELSE 0 END) END) AS avg_procedures_los_5_8_days FROM patients p JOIN admissions a ON p.subject_id = a.subject_id WHERE a.admission_type_id = 2555775 AND a.discharge_status_id = 3710777 AND a.length_of_stay BETWEEN 1 AND 8 AND EXISTS (SELECT 1 FROM procedures_icd pi WHERE pi.subject_id = a.subject_id AND pi.icd_code = '7710777') GROUP BY p.subject_id;